// @pit: {"label": "Strengthen reply footer assertion and update docs about the summary"}
async ({ workspace: { read, edit } }) => {
  const r = await read("src/run.test.ts", { format: "raw" });
  const a = '\t\texpect(w.gh.posted[0]).toContain("### 🤖 pi Response\\n\\nFixed it.");\n\t\texpect(w.gh.posted[0]).toContain(REF);';
  if (!r.content.includes(a)) return "anchor";
  await edit("src/run.test.ts", { revision: r.revision, changes: [{ kind: "replaceFile", content: r.content.replace(a, '\t\texpect(w.gh.posted[0]).toContain("### 🤖 pi Response\\n\\nFixed it.");\n\t\texpect(w.gh.posted[0]).toContain(\n\t\t\t`<summary>🧵 This conversation is stored in git on <code>${REF}</code></summary>`,\n\t\t);\n\t\texpect(w.gh.posted[0]).toContain(`git fetch origin \'${REF}:${REF}\'`);') }] });
  const h = await read("docs/how-it-works.md", { format: "raw" });
  const h1 = "9. **Save.** pi-action pushes the thread, and writes the git commands that read the thread to the job summary. See [Read a thread](threads.md#read-a-thread).";
  const t = await read("docs/threads.md", { format: "raw" });
  const t1 = "The job summary of the run shows them too. Each answer comment of pi-action shows the ref of its thread, and the `git fetch` command.";
  if (!h.content.includes(h1) || !t.content.includes(t1)) return "doc anchors";
  await edit("docs/how-it-works.md", { revision: h.revision, changes: [{ kind: "replaceFile", content: h.content.replace(h1, "9. **Save.** pi-action pushes the thread. Each comment of pi-action ends with a collapsed `🧵 This conversation is stored in git on ...` section with the git commands that read the thread. In `output` mode, the job summary shows these commands. See [Read a thread](threads.md#read-a-thread).") }] });
  await edit("docs/threads.md", { revision: t.revision, changes: [{ kind: "replaceFile", content: t.content.replace(t1, "Each comment of pi-action ends with these commands for its thread, in a collapsed section: `🧵 This conversation is stored in git on refs/pi/threads/<number>`. In `output` mode, pi-action posts no comment, so the job summary of the run shows the commands.") }] });
  return "ok";
}

